const t="zenkamoku-n3-best-workbook",r="w04-d01",e=4,c=1,n="第4週",s="1日目",o=[{type:"grammar_form",title:"文法形式の判断",titleEn:"Selecting grammar form",pageRef:"pp.46–47",instruction:"つぎの文の（　）に入れるのに最もよいものを、１・２・３・４から一つえらびなさい。",questions:[{number:1,stem:"母（　）この絵は捨てることができない大切なものだ。",options:["といえば","にとって","のとおり","について"],correct:2,correctOption:"にとって"},{number:2,stem:"悪いことをしたら、きちんと謝る（　）だと思う。",options:["よう","ため","べき","わけ"],correct:3,correctOption:"べき"},{number:3,stem:"（学校で）<br>工藤「今夜、映画に行かないって聞いたけど本当？」<br>松瀬「うん。明日はテストがあるし、（　）少し頭も痛いんだ。」<br>工藤「そっか。お大事にね。」",options:["それに","どうか","それなら","どうしても"],correct:1,correctOption:"それに"},{number:4,stem:"（電話で）<br>木下「もしもし？ 今朝、メール送ったんだけど、読んでくれた？」<br>神田「ごめん、今、起きた（　）だから、まだ読んでないんだ。」",options:["とたん","とき","ばかり","はず"],correct:3,correctOption:"ばかり"},{number:5,stem:"まだ一度も着ていない新しい服を弟に（　）しまった。",options:["汚れて","汚されて","汚させて","汚させられて"],correct:2,correctOption:"汚されて"},{number:6,stem:"（会社で）<br>西川「部長、高橋様が（　）ました。」<br>部長「そうか。じゃあ、応接室にご案内して。」",options:["お目にかかり","おいでになり","お伺いいたし","お会いになり"],correct:2,correctOption:"おいでになり"},{number:7,stem:"先生の話によると、来週のマラソン大会は（　）。",options:["中止になったとのことだ","中止にしてほしい","中止させようと思う","中止にすることだ"],correct:1,correctOption:"中止になったとのことだ"},{number:8,stem:"兄はいつも、本を（　）全然読まないのに、また何冊も買ってきた。",options:["買わないで","買うだけで","買えなくて","買うせいで"],correct:4,correctOption:"買うせいで"},{number:9,stem:"そのレストランは、やる気さえあれば、（　）働かせてくれる。",options:["経験しているので","経験したくても","経験が長いことで","経験がなくても"],correct:4,correctOption:"経験がなくても"},{number:10,stem:"（電話で）<br>妻「もしもし？ 今、駅に着いたんだけどね、雨が降ってきちゃって。」<br>夫「本当？ じゃあ今、傘を（　）。ちょっと待ってて。」<br>妻「ありがとう。助かる。」",options:["持ってきたよ","持っていくよ","持っているよ","持っておくよ"],correct:2,correctOption:"持っていくよ"},{number:11,stem:"（旅行先で）<br>客「この荷物は、バスまで自分で持っていかなければなりませんか。」<br>ガイド「いいえ、係りがお持ち（　）ので、ご心配なく。」",options:["申します","なさいます","ございます","いたします"],correct:4,correctOption:"いたします"},{number:12,stem:"（スーパーで）<br>子「ねえ、スイカだよ！ これ食べたいよ！」<br>母「これはちょっと（　）すぎるし、今日は車で来てないから運べないよ。」",options:["大き","大きい","大きく","大きくなり"],correct:1,correctOption:"大き"},{number:13,stem:"小泉「有田さん、最近スポーツジムに行ってるって聞きましたよ。」<br>有田「妻に太ったって言われたから、できるだけ（　）。」",options:["運動するようにしたかったんだ","運動するようにしているんだ","運動できるようにしたかったんだ","運動できたらいいと思っていたんだ"],correct:2,correctOption:"運動するようにしているんだ"}]},{type:"text_grammar",title:"文章の文法",titleEn:"Text grammar",pageRef:"pp.48–49",instruction:"つぎの文章を読んで、文章全体の内容を考えて、［１］から［５］の中に入る最もよいものを、１・２・３・４から一つえらびなさい。",passageTitle:"わかりにくい日本語",passage:`スロマン・カイ

　日本語は難しい。文字は３種類もあるし、女性的な言葉と男性的な言葉がある。しかし、私が一番困っているのは、日本語には同じ言葉なのに、意味が全然違うものが多いという［１］だ。

　［２］、「すみません」には「ごめんなさい」「ちょっといいですか」「ありがとう」という意味が、「けっこうです」には「ＯＫです」「いりません」、そして、「いい加減」には「ちょうどいい」「ちゃんとしない」などの意味がある。日本人の友達に、どのように使い分ければいいのかを聞いても、日本人は会話の流れで判断しているから、言葉ではうまく説明ができないという。つまり、［３］。

　また、敬語の使い方もよくわからない。もちろん、年上の人に丁寧に話さなければならないことは［４］、相手との関係が近くなると敬語を使わなくなったり、家ではお父さんのことを「お父さん」と呼んでいるのに、他の人に話すときは「父」と言ったり、本当にわかりにくい。私は、間違えるのが恥ずかしくて、これらの日本語をできるだけ［５］。しかし、それではだめだと気がついた。たくさん間違えてもいいから、少しずつ覚えていこうと思う。

　いつか、日本語を自由に、自然に使えるようになりたい。`,questions:[{number:1,stem:"",options:["そう","もの","よう","こと"],correct:4,correctOption:"こと"},{number:2,stem:"",options:["まるで","例えば","なるほど","すると"],correct:2,correctOption:"例えば"},{number:3,stem:"",options:["慣れているはずだ","慣れるしかない","慣れてきたところだ","慣れるまで待てない"],correct:2,correctOption:"慣れるしかない"},{number:4,stem:"",options:["理解しがたいが","理解させたが","理解できるが","理解したがるが"],correct:3,correctOption:"理解できるが"},{number:5,stem:"",options:["使えるようにしてきた","使えるようにしていく","使わないようにしてきた","使わないようにしていく"],correct:3,correctOption:"使わないようにしてきた"}]}],i={bookId:t,chapterId:r,week:4,day:1,weekTitle:"第4週",dayTitle:"1日目",subSections:o};export{t as bookId,r as chapterId,c as day,s as dayTitle,i as default,o as subSections,e as week,n as weekTitle};
